import Foundation

/// Files the sample vault has besides notes: one picture for embeds (`![[bilayer-diagram.png]]`).
enum FixtureFiles {
    static let files: [String: Data] = [
        "bilayer-diagram.png": Data(base64Encoded: "")!,
    ]

    static func file(named name: String) -> Data? {
        let key = (name as NSString).lastPathComponent.lowercased()
        return files.first { $0.key.lowercased() == key }?.value
    }
}
